61	static void set_mem_access(MCInst *MI, bool status)
62	{
63		if (MI->csh->detail != CS_OPT_ON)
64			return;
65	
66		MI->csh->doing_mem = status;
67		if (!status)
68			// done, create the next operand slot
69			MI->flat_insn->detail->x86.op_count++;
70	
71	}
