73	static void printopaquemem(MCInst *MI, unsigned OpNo, SStream *O)
74	{
75		// FIXME: do this with autogen
76		// printf(">>> ID = %u\n", MI->flat_insn->id);
77		switch(MI->flat_insn->id) {
78			default:
79				SStream_concat0(O, "ptr ");
80				break;
81			case X86_INS_SGDT:
82			case X86_INS_SIDT:
83			case X86_INS_LGDT:
84			case X86_INS_LIDT:
85			case X86_INS_FXRSTOR:
86			case X86_INS_FXSAVE:
87			case X86_INS_LJMP:
88			case X86_INS_LCALL:
89				// do not print "ptr"
90				break;
91		}
92	
93		switch(MI->csh->mode) {
94			case CS_MODE_16:
95				switch(MI->flat_insn->id) {
96					default:
97						MI->x86opsize = 2;
98						break;
99					case X86_INS_LJMP:
100					case X86_INS_LCALL:
101						MI->x86opsize = 4;
102						break;
103					case X86_INS_SGDT:
104					case X86_INS_SIDT:
105					case X86_INS_LGDT:
106					case X86_INS_LIDT:
107						MI->x86opsize = 6;
108						break;
109				}
110				break;
111			case CS_MODE_32:
112				switch(MI->flat_insn->id) {
113					default:
114						MI->x86opsize = 4;
115						break;
116					case X86_INS_LJMP:
117					case X86_INS_JMP:
118					case X86_INS_LCALL:
119					case X86_INS_SGDT:
120					case X86_INS_SIDT:
121					case X86_INS_LGDT:
122					case X86_INS_LIDT:
123						MI->x86opsize = 6;
124						break;
125				}
126				break;
127			case CS_MODE_64:
128				switch(MI->flat_insn->id) {
129					default:
130						MI->x86opsize = 8;
131						break;
132					case X86_INS_LJMP:
133					case X86_INS_LCALL:
134					case X86_INS_SGDT:
135					case X86_INS_SIDT:
136					case X86_INS_LGDT:
137					case X86_INS_LIDT:
138						MI->x86opsize = 10;
139						break;
140				}
141				break;
142			default:	// never reach
143				break;
144		}
145	
146		printMemReference(MI, OpNo, O);
147	}
