405	#ifndef CAPSTONE_DIET
406	// copy & normalize access info
407	static void get_op_access(cs_struct *h, unsigned int id, uint8_t *access, uint64_t *eflags)
408	{
409	#ifndef CAPSTONE_DIET
410		uint8_t i;
411		uint8_t *arr = X86_get_op_access(h, id, eflags);
412	
413		if (!arr) {
414			access[0] = 0;
415			return;
416		}
417	
418		// copy to access but zero out CS_AC_IGNORE
419		for(i = 0; arr[i]; i++) {
420			if (arr[i] != CS_AC_IGNORE)
421				access[i] = arr[i];
422			else
423				access[i] = 0;
424		}
425	
426		// mark the end of array
427		access[i] = 0;
428	#endif
429	}
430	#endif
