475	static void printDstIdx(MCInst *MI, unsigned Op, SStream *O)
476	{
477		if (MI->csh->detail) {
478	#ifndef CAPSTONE_DIET
479			uint8_t access[6];
480	#endif
481	
482			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_MEM;
483			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->x86opsize;
484			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.segment = X86_REG_INVALID;
485			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.base = X86_REG_INVALID;
486			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.index = X86_REG_INVALID;
487			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.scale = 1;
488			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = 0;
489	
490	#ifndef CAPSTONE_DIET
491			get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
492			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
493	#endif
494		}
495	
496		// DI accesses are always ES-based on non-64bit mode
497		if (MI->csh->mode != CS_MODE_64) {
498			SStream_concat(O, "es:[");
499			if (MI->csh->detail) {
500				MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.segment = X86_REG_ES;
501			}
502		} else
503			SStream_concat(O, "[");
504	
505		set_mem_access(MI, true);
506		printOperand(MI, Op, O);
507		SStream_concat0(O, "]");
508		set_mem_access(MI, false);
509	}
