567	static void printMemOffset(MCInst *MI, unsigned Op, SStream *O)
568	{
569		MCOperand *DispSpec = MCInst_getOperand(MI, Op);
570		MCOperand *SegReg = MCInst_getOperand(MI, Op + 1);
571		int reg;
572	
573		if (MI->csh->detail) {
574	#ifndef CAPSTONE_DIET
575			uint8_t access[6];
576	#endif
577	
578			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_MEM;
579			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->x86opsize;
580			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.segment = X86_REG_INVALID;
581			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.base = X86_REG_INVALID;
582			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.index = X86_REG_INVALID;
583			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.scale = 1;
584			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = 0;
585	
586	#ifndef CAPSTONE_DIET
587			get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
588			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
589	#endif
590		}
591	
592		// If this has a segment register, print it.
593		reg = MCOperand_getReg(SegReg);
594		if (reg) {
595			_printOperand(MI, Op + 1, O);
596			SStream_concat0(O, ":");
597			if (MI->csh->detail) {
598				MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.segment = X86_register_map(reg);
599			}
600		}
601	
602		SStream_concat0(O, "[");
603	
604		if (MCOperand_isImm(DispSpec)) {
605			int64_t imm = MCOperand_getImm(DispSpec);
606			if (MI->csh->detail)
607				MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = imm;
608	
609			if (imm < 0)
610				printImm(MI, O, arch_masks[MI->csh->mode] & imm, true);
611			else
612				printImm(MI, O, imm, true);
613		}
614	
615		SStream_concat0(O, "]");
616	
617		if (MI->csh->detail)
618			MI->flat_insn->detail->x86.op_count++;
619	
620		if (MI->op1_size == 0)
621			MI->op1_size = MI->x86opsize;
622	}
