624	static void printU8Imm(MCInst *MI, unsigned Op, SStream *O)
625	{
626		uint8_t val = MCOperand_getImm(MCInst_getOperand(MI, Op)) & 0xff;
627	
628		printImm(MI, O, val, true);
629	
630		if (MI->csh->detail) {
631	#ifndef CAPSTONE_DIET
632			uint8_t access[6];
633	#endif
634	
635			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_IMM;
636			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].imm = val;
637			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = 1;
638	
639	#ifndef CAPSTONE_DIET
640			get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
641			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
642	#endif
643	
644			MI->flat_insn->detail->x86.op_count++;
645		}
646	}
