679	static void printInstruction(MCInst *MI, SStream *O);
680	
681	void X86_Intel_printInst(MCInst *MI, SStream *O, void *Info)
682	{
683	#ifndef CAPSTONE_DIET
684		char *mnem;
685	#endif
686		x86_reg reg, reg2;
687		enum cs_ac_type access1, access2;
688	
689		// perhaps this instruction does not need printer
690		if (MI->assembly[0]) {
691			strncpy(O->buffer, MI->assembly, sizeof(O->buffer));
692			return;
693		}
694	
695	#ifndef CAPSTONE_DIET
696		// Try to print any aliases first.
697		mnem = printAliasInstr(MI, O);
698		if (mnem)
699			cs_mem_free(mnem);
700		else
701	#endif
702		{
703			X86_lockrep(MI, O);
704			printInstruction(MI, O);
705		}
706	
707		reg = X86_insn_reg_intel(MCInst_getOpcode(MI), &access1);
708		if (MI->csh->detail) {
709	#ifndef CAPSTONE_DIET
710			uint8_t access[6] = {0};
711	#endif
712	
713			// first op can be embedded in the asm by llvm.
714			// so we have to add the missing register as the first operand
715			if (reg) {
716				// shift all the ops right to leave 1st slot for this new register op
717				memmove(&(MI->flat_insn->detail->x86.operands[1]), &(MI->flat_insn->detail->x86.operands[0]),
718						sizeof(MI->flat_insn->detail->x86.operands[0]) * (ARR_SIZE(MI->flat_insn->detail->x86.operands) - 1));
719				MI->flat_insn->detail->x86.operands[0].type = X86_OP_REG;
720				MI->flat_insn->detail->x86.operands[0].reg = reg;
721				MI->flat_insn->detail->x86.operands[0].size = MI->csh->regsize_map[reg];
722				MI->flat_insn->detail->x86.operands[0].access = access1;
723				MI->flat_insn->detail->x86.op_count++;
724			} else {
725				if (X86_insn_reg_intel2(MCInst_getOpcode(MI), &reg, &access1, &reg2, &access2)) {
726					MI->flat_insn->detail->x86.operands[0].type = X86_OP_REG;
727					MI->flat_insn->detail->x86.operands[0].reg = reg;
728					MI->flat_insn->detail->x86.operands[0].size = MI->csh->regsize_map[reg];
729					MI->flat_insn->detail->x86.operands[0].access = access1;
730					MI->flat_insn->detail->x86.operands[1].type = X86_OP_REG;
731					MI->flat_insn->detail->x86.operands[1].reg = reg2;
732					MI->flat_insn->detail->x86.operands[1].size = MI->csh->regsize_map[reg2];
733					MI->flat_insn->detail->x86.operands[1].access = access2;
734					MI->flat_insn->detail->x86.op_count = 2;
735				}
736			}
737	
738	#ifndef CAPSTONE_DIET
739			get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
740			MI->flat_insn->detail->x86.operands[0].access = access[0];
741			MI->flat_insn->detail->x86.operands[1].access = access[1];
742	#endif
743		}
744	
745		if (MI->op1_size == 0 && reg)
746			MI->op1_size = MI->csh->regsize_map[reg];
747	}
748	
749	/// printPCRelImm - This is used to print an immediate value that ends up
750	/// being encoded as a pc-relative value.
751	static void printPCRelImm(MCInst *MI, unsigned OpNo, SStream *O)
752	{
753		MCOperand *Op = MCInst_getOperand(MI, OpNo);
754		if (MCOperand_isImm(Op)) {
755			int64_t imm = MCOperand_getImm(Op) + MI->flat_insn->size + MI->address;
756			uint8_t opsize = X86_immediate_size(MI->Opcode, NULL);
757	
758			// truncat imm for non-64bit
759			if (MI->csh->mode != CS_MODE_64) {
760				imm = imm & 0xffffffff;
761			}
762	
763			printImm(MI, O, imm, true);
764	
765			if (MI->csh->detail) {
766	#ifndef CAPSTONE_DIET
767				uint8_t access[6];
768	#endif
769	
770				MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_IMM;
771				// if op_count > 0, then this operand's size is taken from the destination op
772				if (MI->flat_insn->detail->x86.op_count > 0)
773					MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->flat_insn->detail->x86.operands[0].size;
774				else if (opsize > 0)
775					MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = opsize;
776				else
777					MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->imm_size;
778				MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].imm = imm;
779	
780	#ifndef CAPSTONE_DIET
781				get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
782				MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
783	#endif
784	
785				MI->flat_insn->detail->x86.op_count++;
786			}
787	
788			if (MI->op1_size == 0)
789				MI->op1_size = MI->imm_size;
790		}
791	}
792	
793	static void printOperand(MCInst *MI, unsigned OpNo, SStream *O)
794	{
795		MCOperand *Op  = MCInst_getOperand(MI, OpNo);
796	
797		if (MCOperand_isReg(Op)) {
798			unsigned int reg = MCOperand_getReg(Op);
799	
800			printRegName(O, reg);
801			if (MI->csh->detail) {
802				if (MI->csh->doing_mem) {
803					MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.base = X86_register_map(reg);
804				} else {
805	#ifndef CAPSTONE_DIET
806					uint8_t access[6];
807	#endif
808	
809					MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_REG;
810					MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].reg = X86_register_map(reg);
811					MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->csh->regsize_map[X86_register_map(reg)];
812	
813	#ifndef CAPSTONE_DIET
814					get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
815					MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
816	#endif
817	
818					MI->flat_insn->detail->x86.op_count++;
819				}
820			}
821	
822			if (MI->op1_size == 0)
823				MI->op1_size = MI->csh->regsize_map[X86_register_map(reg)];
824		} else if (MCOperand_isImm(Op)) {
825			uint8_t encsize;
826			int64_t imm = MCOperand_getImm(Op);
827			uint8_t opsize = X86_immediate_size(MCInst_getOpcode(MI), &encsize);
828	
829			if (opsize == 1)    // print 1 byte immediate in positive form
830				imm = imm & 0xff;
831	
832			// printf(">>> id = %u\n", MI->flat_insn->id);
833			switch(MI->flat_insn->id) {
834				default:
835					printImm(MI, O, imm, MI->csh->imm_unsigned);
836					break;
837	
838				case X86_INS_MOVABS:
839				case X86_INS_MOV:
840					// do not print number in negative form
841					printImm(MI, O, imm, true);
842					break;
843	
844				case X86_INS_IN:
845				case X86_INS_OUT:
846				case X86_INS_INT:
847					// do not print number in negative form
848					imm = imm & 0xff;
849					printImm(MI, O, imm, true);
850					break;
851	
852				case X86_INS_LCALL:
853				case X86_INS_LJMP:
854				case X86_INS_JMP:
855					// always print address in positive form
856					if (OpNo == 1) {	// ptr16 part
857						imm = imm & 0xffff;
858						opsize = 2;
859					} else
860						opsize = 4;
861					printImm(MI, O, imm, true);
862					break;
863	
864				case X86_INS_AND:
865				case X86_INS_OR:
866				case X86_INS_XOR:
867					// do not print number in negative form
868					if (imm >= 0 && imm <= HEX_THRESHOLD)
869						printImm(MI, O, imm, true);
870					else {
871						imm = arch_masks[opsize? opsize : MI->imm_size] & imm;
872						printImm(MI, O, imm, true);
873					}
874					break;
875	
876				case X86_INS_RET:
877				case X86_INS_RETF:
878					// RET imm16
879					if (imm >= 0 && imm <= HEX_THRESHOLD)
880						printImm(MI, O, imm, true);
881					else {
882						imm = 0xffff & imm;
883						printImm(MI, O, imm, true);
884					}
885					break;
886			}
887	
888			if (MI->csh->detail) {
889				if (MI->csh->doing_mem) {
890					MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = imm;
891				} else {
892	#ifndef CAPSTONE_DIET
893					uint8_t access[6];
894	#endif
895	
896					MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_IMM;
897					if (opsize > 0) {
898						MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = opsize;
899						MI->flat_insn->detail->x86.encoding.imm_size = encsize;
900					} else if (MI->flat_insn->detail->x86.op_count > 0) {
901						if (MI->flat_insn->id != X86_INS_LCALL && MI->flat_insn->id != X86_INS_LJMP) {
902							MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size =
903								MI->flat_insn->detail->x86.operands[0].size;
904						} else
905							MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->imm_size;
906					} else
907						MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->imm_size;
908					MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].imm = imm;
909	
910	#ifndef CAPSTONE_DIET
911					get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
912					MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
913	#endif
914	
915					MI->flat_insn->detail->x86.op_count++;
916				}
917			}
918		}
919	}
920	
921	static void printMemReference(MCInst *MI, unsigned Op, SStream *O)
922	{
923		bool NeedPlus = false;
924		MCOperand *BaseReg  = MCInst_getOperand(MI, Op + X86_AddrBaseReg);
925		uint64_t ScaleVal = MCOperand_getImm(MCInst_getOperand(MI, Op + X86_AddrScaleAmt));
926		MCOperand *IndexReg  = MCInst_getOperand(MI, Op + X86_AddrIndexReg);
927		MCOperand *DispSpec = MCInst_getOperand(MI, Op + X86_AddrDisp);
928		MCOperand *SegReg = MCInst_getOperand(MI, Op + X86_AddrSegmentReg);
929		int reg;
930	
931		if (MI->csh->detail) {
932	#ifndef CAPSTONE_DIET
933			uint8_t access[6];
934	#endif
935	
936			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_MEM;
937			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->x86opsize;
938			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.segment = X86_REG_INVALID;
939			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.base = X86_register_map(MCOperand_getReg(BaseReg));
940			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.index = X86_register_map(MCOperand_getReg(IndexReg));
941			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.scale = (int)ScaleVal;
942			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = 0;
943	
944	#ifndef CAPSTONE_DIET
945			get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
946			MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
947	#endif
948		}
949	
950		// If this has a segment register, print it.
951		reg = MCOperand_getReg(SegReg);
952		if (reg) {
953			_printOperand(MI, Op + X86_AddrSegmentReg, O);
954			if (MI->csh->detail) {
955				MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.segment = X86_register_map(reg);
956			}
957			SStream_concat0(O, ":");
958		}
959	
960		SStream_concat0(O, "[");
961	
962		if (MCOperand_getReg(BaseReg)) {
963			_printOperand(MI, Op + X86_AddrBaseReg, O);
964			NeedPlus = true;
965		}
966	
967		if (MCOperand_getReg(IndexReg)) {
968			if (NeedPlus) SStream_concat0(O, " + ");
969			_printOperand(MI, Op + X86_AddrIndexReg, O);
970			if (ScaleVal != 1)
971				SStream_concat(O, "*%u", ScaleVal);
972			NeedPlus = true;
973		}
974	
975		if (MCOperand_isImm(DispSpec)) {
976			int64_t DispVal = MCOperand_getImm(DispSpec);
977			if (MI->csh->detail)
978				MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = DispVal;
979			if (DispVal) {
980				if (NeedPlus) {
981					if (DispVal < 0) {
982						SStream_concat0(O, " - ");
983						printImm(MI, O, -DispVal, true);
984					} else {
985						SStream_concat0(O, " + ");
986						printImm(MI, O, DispVal, true);
987					}
988				} else {
989					// memory reference to an immediate address
990					if (MI->csh->mode == CS_MODE_64)
991						MI->op1_size = 8;
992					if (DispVal < 0) {
993						printImm(MI, O, arch_masks[MI->csh->mode] & DispVal, true);
994					} else {
995						printImm(MI, O, DispVal, true);
996					}
997				}
998	
999			} else {
1000				// DispVal = 0
1001				if (!NeedPlus)	// [0]
1002					SStream_concat0(O, "0");
1003			}
1004		}
1005	
1006		SStream_concat0(O, "]");
1007	
1008		if (MI->csh->detail)
1009			MI->flat_insn->detail->x86.op_count++;
1010	
1011		if (MI->op1_size == 0)
1012			MI->op1_size = MI->x86opsize;
1013	}
1014	
1015	static void printanymem(MCInst *MI, unsigned OpNo, SStream *O)
1016	{
1017		switch(MI->Opcode) {
1018			default: break;
1019			case X86_LEA16r:
1020					 MI->x86opsize = 2;
1021					 break;
1022			case X86_LEA32r:
1023			case X86_LEA64_32r:
1024					 MI->x86opsize = 4;
1025					 break;
1026			case X86_LEA64r:
1027					 MI->x86opsize = 8;
1028					 break;
1029		}
1030		printMemReference(MI, OpNo, O);
1031	}
