#include <stdio.h>
#include <capstone/capstone.h>

int main() {
    csh handle;
    cs_insn *insn;
    size_t count;

    // CVTSD2SI64rm instruction - cvtsd2si rax, [rbx]
    // This should trigger the alias printing path
    unsigned char code[] = {
        0x48, 0x0f, 0x2d, 0x03  // cvtsd2si rax, qword ptr [rbx]
    };

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &handle) != CS_ERR_OK) {
        printf("ERROR: Failed to initialize engine!\n");
        return -1;
    }

    cs_option(handle, CS_OPT_SYNTAX, CS_OPT_SYNTAX_INTEL);
    cs_option(handle, CS_OPT_DETAIL, CS_OPT_ON);

    count = cs_disasm(handle, code, sizeof(code), 0x1000, 0, &insn);
    if (count > 0) {
        for (size_t i = 0; i < count; i++) {
            printf("0x%"PRIx64":\t%s\t\t%s\n", insn[i].address, insn[i].mnemonic, insn[i].op_str);
        }
        cs_free(insn, count);
    } else {
        printf("ERROR: Failed to disassemble!\n");
    }

    cs_close(&handle);
    return 0;
}

